<script setup lang="ts">
import { computed, ref, watch } from 'vue';
import { invoke } from '@tauri-apps/api/core';
import { open as openFile, save as saveFile } from '@tauri-apps/plugin-dialog';
import { HISENSE_BUTTONS, type HisenseConfig, type InstalledApplication } from '../types/hisense';
import ApplicationPicker from './ApplicationPicker.vue';
const props=defineProps<{open:boolean}>();
const emit=defineEmits<{close:[];applied:[config:HisenseConfig]}>();
type Document=Record<string,any>;
type Result={document:Document;config:HisenseConfig;applications:Array<{original:string;target:string|null;message:string}>;applied:boolean};
const text=ref(''),mode=ref<'mapping'|'macros'>('mapping'),busy=ref(false),message=ref(''),result=ref<Result|null>(null);
const section=ref('default'),button=ref('ok'),trigger=ref('single'),actionText=ref(''),picker=ref(false);
const document=computed<Document|null>(()=>{try{return JSON.parse(text.value);}catch{return null;}});
const scopes=computed(()=>[['default','桌面默认'],...Object.entries(document.value?.profiles||{}).map(([id,p])=>[id,(p as {name:string}).name])]);
function readAction(){const d=document.value;if(!d)return;const s=section.value==='default'?d:d.profiles?.[section.value];if(!s)return;const a=trigger.value==='single'?s.button_bindings?.[button.value]:trigger.value==='long'?s.long_press_bindings?.[button.value]:s.multi_click_bindings?.[button.value]?.[trigger.value];actionText.value=JSON.stringify(a||{type:'None'},null,2);}
watch([section,button,trigger],readAction);
async function load(kind:'mapping'|'macros'=mode.value){busy.value=true;message.value='';result.value=null;try{mode.value=kind;text.value=JSON.stringify(await invoke('hisense_mapping_document',{macrosOnly:kind==='macros'}),null,2);section.value='default';readAction();}catch(e){message.value=String(e);}finally{busy.value=false;}}
function writeAction(){try{const d=JSON.parse(text.value),a=JSON.parse(actionText.value);const s=section.value==='default'?d:d.profiles?.[section.value];if(!s)throw Error('请先选择有效的应用配置');s.button_bindings||={};s.long_press_bindings||={};s.multi_click_bindings||={};if(section.value!=='default'&&s.button_bindings[button.value]===undefined)s.button_bindings[button.value]=structuredClone(d.button_bindings[button.value]||{type:'None'});if(trigger.value==='single'){s.button_bindings[button.value]=a;if(['PointerConfirm','PointerAi','TouchDrag','VoiceInput'].includes(a.type)){delete s.long_press_bindings[button.value];delete s.multi_click_bindings[button.value];}}else if(trigger.value==='long')s.long_press_bindings[button.value]=a;else{ s.multi_click_bindings[button.value]||={};s.multi_click_bindings[button.value][trigger.value]=a; }text.value=JSON.stringify(d,null,2);result.value=null;message.value='动作已写入文档，点击“应用到遥控器”后生效。';}catch(e){message.value=String(e);}}
async function parse(apply=false){busy.value=true;message.value='正在解析并自动查找对应的本机应用…';try{const r=await invoke<Result>('hisense_parse_mappings',{text:text.value,apply});result.value=r;text.value=JSON.stringify(r.document,null,2);mode.value=r.document.format==='salohub-macros'?'macros':'mapping';readAction();if(apply)emit('applied',r.config);message.value=apply?'已应用并保存；未找到的应用保留原关联，请选择本机程序后重新应用。':'解析通过，尚未修改配置。请核对应用关联和内容后再应用。';}catch(e){result.value=null;message.value=`未修改配置：${e}`;}finally{busy.value=false;}}
async function importFile(){try{const path=await openFile({multiple:false,filters:[{name:'映射或宏 JSON',extensions:['json']}]});if(typeof path!=='string')return;busy.value=true;text.value=await invoke('hisense_read_mapping_file',{path});mode.value=document.value?.format==='salohub-macros'?'macros':'mapping';busy.value=false;await parse();}catch(e){message.value=String(e);}finally{busy.value=false;}}
async function exportFile(){try{const path=await saveFile({defaultPath:mode.value==='macros'?'SaloHUb-macros.json':'SaloHUb-mappings.json',filters:[{name:'JSON',extensions:['json']}]});if(!path)return;await invoke('hisense_export_document',{path,text:text.value});message.value='已导出。映射文件包含应用配置及其引用的宏；宏文件可合并到其他电脑。';}catch(e){message.value=String(e);}}
const relink=ref('');function chooseApp(app:InstalledApplication){if(relink.value){text.value=text.value.split(JSON.stringify(relink.value)).join(JSON.stringify(app.launch_id?`shell:AppsFolder\\${app.launch_id}`:app.path));result.value=null;message.value='已替换应用路径，请重新解析或应用。';relink.value='';}else{actionText.value=JSON.stringify({type:'LaunchApp',value:app.launch_id?`shell:AppsFolder\\${app.launch_id}`:app.path},null,2);}}
watch(()=>props.open,open=>{if(open)void load('mapping');});
</script>
<template><div v-if="open" class="workbench-mask" @click.self="!busy&&emit('close')"><section class="workbench" role="dialog" aria-modal="true" aria-label="按键映射与宏解析器" @keydown.esc.stop="!busy&&emit('close')">
<header><div><h2>按键映射与宏解析器</h2><p>直接编辑 JSON，解析后应用。导入会自动查找本机应用，不会启动程序。</p></div><button :disabled="busy" @click="emit('close')">×</button></header>
<div class="workbench-tools"><button :disabled="busy" :class="{active:mode==='mapping'}" @click="load('mapping')">全部按键映射</button><button :disabled="busy" :class="{active:mode==='macros'}" @click="load('macros')">独立宏库</button><button :disabled="busy" @click="importFile">导入文件</button><button :disabled="busy" @click="exportFile">导出当前文档</button><small>切换文档会载入已保存内容</small></div>
<div class="workbench-body"><aside v-if="mode==='mapping'"><h3>编辑按键动作</h3><label>应用配置<select v-model="section"><option v-for="[id,name] in scopes" :key="id" :value="id">{{ name }}</option></select></label><label>遥控按键<select v-model="button"><option v-for="[id,name] in HISENSE_BUTTONS" :key="id" :value="id">{{ name }}</option></select></label><label>触发方式<select v-model="trigger"><option value="single">单击 / 基础动作</option><option value="long">长按</option><option v-for="n in [2,3,4]" :key="n" :value="String(n)">{{ n }} 连击</option></select></label><button @click="readAction">读取文档中的动作</button><textarea v-model="actionText" aria-label="动作 JSON" spellcheck="false" /><button @click="relink='';picker=true">从本机应用选择启动动作</button><button class="primary" :disabled="busy" @click="writeAction">写入右侧文档</button><p>示例：<code>{"type":"SingleKey","value":33}</code> 是 Page Up。组合键用 ComboKey，引用宏用 Macro 和宏 ID。</p></aside>
<main><label>可编辑文档<textarea v-model="text" aria-label="映射与宏 JSON 文档" spellcheck="false" :disabled="busy" @input="result=null" /></label><p class="workbench-message" role="status">{{ message }}</p><div v-if="result?.applications.length" class="resolution-list"><h3>本机应用关联</h3><div v-for="r in result.applications" :key="r.original"><strong>{{ r.original }}</strong><small>{{ r.target||r.message }}</small><button v-if="!r.target&&!r.original.startsWith('配置：')" @click="relink=r.original;picker=true">选择对应应用</button></div></div></main></div>
<footer><span>格式错误不会覆盖配置。独立宏导入按 ID 合并；相同 ID 会更新。</span><button :disabled="busy" @click="parse(false)">解析与检查关联</button><button class="primary" :disabled="busy" @click="parse(true)">{{ busy?'处理中…':'应用到遥控器' }}</button></footer>
</section><ApplicationPicker :open="picker" @close="picker=false" @select="chooseApp" /></div></template>
<style scoped>
.workbench-mask{position:fixed;inset:0;z-index:3600;background:var(--overlay);display:grid;place-items:center;padding:24px}.workbench{width:min(1200px,96vw);height:min(860px,92vh);background:var(--card-bg);color:var(--text);border:1px solid var(--border);border-radius:16px;display:flex;flex-direction:column;overflow:hidden;box-shadow:var(--dialog-shadow)}header,footer,.workbench-tools{display:flex;align-items:center;gap:10px;padding:16px 22px;border-bottom:1px solid var(--border)}header{justify-content:space-between}h2{margin:0;font-size:20px}h3{font-size:14px;margin:0 0 12px}p,small,footer span{font-size:12px;color:var(--text-secondary);line-height:1.7}header p{margin-bottom:0}.workbench-tools{flex-wrap:wrap}.workbench-body{display:flex;flex:1;min-height:0}aside{width:270px;flex-shrink:0;padding:20px;overflow:auto;border-right:1px solid var(--border);display:flex;flex-direction:column;gap:12px}main{flex:1;min-width:0;display:flex;flex-direction:column;padding:20px;overflow:auto}label{display:flex;flex-direction:column;gap:8px;font-size:12px}main>label{flex:1;min-height:260px}textarea{resize:vertical;min-height:110px;font:12px/1.65 ui-monospace,Consolas,monospace;tab-size:2}main textarea{flex:1;resize:none;white-space:pre;overflow:auto;min-height:250px}button,select,textarea{color:var(--text);background:var(--card-bg);border:1px solid var(--border);border-radius:8px;padding:9px 11px;font-size:12px}button{cursor:pointer}button.active{border-color:var(--primary);color:var(--primary)}button:disabled{opacity:.5}.primary{background:var(--primary);color:white;border-color:var(--primary)}footer{border-top:1px solid var(--border);border-bottom:0}footer span{flex:1}.workbench-message{white-space:pre-wrap;overflow-wrap:anywhere}.resolution-list>div{padding:10px 0;border-top:1px solid var(--border);font-size:12px;overflow-wrap:anywhere}.resolution-list small{display:block}.resolution-list{max-height:180px;overflow:auto}code{overflow-wrap:anywhere}@media(max-width:780px){aside{width:210px}.workbench-mask{padding:10px}.workbench{width:98vw}footer{flex-wrap:wrap}}
</style>
